import numpy as np
from scipy.spatial.distance import cdist
from rdkit import Chem
L=np.load('ligand_coords.npy');R=np.load('ring_coords.npy');m=Chem.MolFromMolFile('ligand_bound.mol',removeHs=False)
D=cdist(L,R);ii,jj=np.where(D<2.5)
print('intermolecule <2.5')
for i,j in zip(ii,jj):print(i,m.GetAtomWithIdx(int(i)).GetSymbol(),j,'C' if j<7 else 'H',D[i,j])
print('Pd ligand neighbours:',[(i,m.GetAtomWithIdx(i).GetSymbol(),float(np.linalg.norm(p))) for i,p in enumerate(L) if np.linalg.norm(p)<3.5])
print('Pd ring distances',np.linalg.norm(R,axis=1))
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(13,6))
for k,(elev,azim) in enumerate([(80,-90),(20,-70)]):
 ax=fig.add_subplot(1,2,k+1,projection='3d');ax.view_init(elev=elev,azim=azim)
 colors={'C':'#555555','H':'#cccccc','P':'orange','O':'red','Pd':'blue'}
 for i,p in enumerate(L):
  e=m.GetAtomWithIdx(i).GetSymbol();ax.scatter(*p,s=80 if e!='H' else 15,color=colors[e])
 for b in m.GetBonds():
  q=L[[b.GetBeginAtomIdx(),b.GetEndAtomIdx()]];ax.plot(q[:,0],q[:,1],q[:,2],color='gray')
 for i,p in enumerate(R):ax.scatter(*p,s=80 if i<7 else 15,color='green' if i<7 else '#cccccc')
 r=Chem.AddHs(Chem.MolFromSmiles('C1=CC=CC=CC1'))
 for b in r.GetBonds():
  q=R[[b.GetBeginAtomIdx(),b.GetEndAtomIdx()]];ax.plot(q[:,0],q[:,1],q[:,2],color='green')
 for i in [8,25]:
  q=np.array([L[i],[0,0,0]]);ax.plot(q[:,0],q[:,1],q[:,2],color='blue')
 for i in [0,1]:
  q=np.array([R[i],[0,0,0]]);ax.plot(q[:,0],q[:,1],q[:,2],color='blue')
 ax.scatter(0,0,0,color='blue',s=120)
 ax.set_box_aspect([1,1,1]);ax.set_xlim(-7,7);ax.set_ylim(-7,7);ax.set_zlim(-7,7)
plt.tight_layout();plt.savefig('complex.png',dpi=150)
